import sys,os,time,json,hashlib,unittest
from pathlib import Path
root=Path("/mnt/c/Users/s-a-balashov/.codex/worktrees/finite-component-study/VAST")
sys.path[:0]=[str(root/"scripts"),str(root/"tests")]
paths=["scripts/canonical_systems_study_plan_v1.py","scripts/reduce_canonical_systems_study_v1.py","tests/test_canonical_systems_study_plan_v1.py","tests/test_reduce_canonical_systems_study_v1.py"]
def epoch(st): return [st.st_dev,st.st_ino,st.st_mode,st.st_nlink,st.st_size,st.st_mtime_ns,st.st_ctime_ns]
def snapshot(path,fd):
 st=os.fstat(fd); body=bytearray()
 while len(body)<st.st_size:
  part=os.pread(fd,min(1048576,st.st_size-len(body)),len(body))
  if not part: raise AssertionError("source read EOF")
  body.extend(part)
 if os.pread(fd,1,st.st_size) or epoch(os.fstat(fd))!=epoch(st) or epoch(os.lstat(path))!=epoch(st): raise AssertionError("source epoch drift")
 return {"path":str(path),"size_bytes":st.st_size,"sha256":hashlib.sha256(body).hexdigest(),"seven_epochs":epoch(st)}
owner_text=Path("/proc/self/stat").read_text(); tail=owner_text[owner_text.rfind(")")+2:].split()
owner={"pid":os.getpid(),"ppid":os.getppid(),"pgid":os.getpgrp(),"sid":os.getsid(0),"start_ticks":int(tail[19]),"boot_id":Path("/proc/sys/kernel/random/boot_id").read_text().strip()}
fd_before=len(os.listdir("/proc/self/fd"));held=[];before=[];after=[];close_errors=[];events=[];result=None;failure=None;started=time.monotonic()
class Recorded(unittest.TextTestResult):
 def startTest(self,test): events.append({"type":"start","test_id":test.id()});super().startTest(test)
 def addSuccess(self,test): events.append({"type":"success","test_id":test.id()});super().addSuccess(test)
 def addFailure(self,test,err): events.append({"type":"failure","test_id":test.id()});super().addFailure(test,err)
 def addError(self,test,err): events.append({"type":"error","test_id":test.id()});super().addError(test,err)
 def addSkip(self,test,reason): events.append({"type":"skip","test_id":test.id(),"reason":reason});super().addSkip(test,reason)
try:
 for relative in paths:
  path=root/relative;fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW);held.append((path,fd));before.append(snapshot(path,fd))
 suite=unittest.TestSuite()
 for name in ("test_canonical_systems_study_plan_v1","test_reduce_canonical_systems_study_v1"): suite.addTests(unittest.defaultTestLoader.loadTestsFromName(name))
 result=unittest.TextTestRunner(verbosity=2,resultclass=Recorded).run(suite)
 after=[snapshot(p,f) for p,f in held]
 if before!=after: raise AssertionError("owned source before/after drift")
except BaseException as exc: failure=type(exc).__name__+": "+str(exc)
finally:
 for path,fd in reversed(held):
  try:os.close(fd)
  except OSError as exc:close_errors.append(str(exc))
fd_after=len(os.listdir("/proc/self/fd"))
successful=result is not None and result.wasSuccessful() and failure is None and not close_errors and fd_before==fd_after
print(json.dumps({"kind":"finite-study-owned-pure-test-result","successful":successful,"tests_run":result.testsRun if result else None,"failures":len(result.failures) if result else None,"errors":len(result.errors) if result else None,"skips":len(result.skipped) if result else None,"events":events,"source_before":before,"source_after":after,"source_stable":before==after,"source_fds_acquired":len(held),"source_fds_released":not close_errors,"FD_before":fd_before,"FD_after":fd_after,"close_errors":close_errors,"first_failure":failure,"owner":owner,"elapsed_s":time.monotonic()-started,"fixture_only":True},separators=(",",":")))
raise SystemExit(0 if successful else 1)
